using System.Text.Json; using Astronomy.MediaFactory.Core.DocumentaryBlueprint;
namespace Astronomy.MediaFactory.Tests.DocumentaryBlueprint; public sealed class DocumentaryMediaProjectionPolicyTests { [Fact] public void Certified_policy_is_valid_and_json_cannot_bypass_validation(){var p=DocumentaryMediaProjectionFixture.Orion().Policy;Assert.True(DocumentaryMediaProjectionValidator.PolicyValid(p));var json=DocumentaryMediaProjectionFixture.Json(p).Replace("\"requireCompleteMaterialization\":true","\"requireCompleteMaterialization\":false",StringComparison.Ordinal);Assert.ThrowsAny<Exception>(()=>JsonSerializer.Deserialize<DocumentaryMediaProjectionPolicy>(json,DocumentaryMediaProjectionFixture.WebJson));} }
